module TopModule (
    input  logic        clk,
    input  logic        areset,

    input  logic        predict_valid,
    input  logic [6:0]  predict_pc,
    output logic        predict_taken,
    output logic [6:0]  predict_history,

    input  logic        train_valid,
    input  logic        train_taken,
    input  logic        train_mispredicted,
    input  logic [6:0]  train_history,
    input  logic [6:0]  train_pc
);

    // 7-bit Global History Register (GHR)
    logic [6:0] ghr;

    // Pattern History Table (PHT): 128 entries of 2-bit saturating counters
    logic [1:0] pht [127:0];

    // Prediction interface logic (combinational)
    logic [6:0] predict_index;
    assign predict_index   = predict_pc ^ ghr;
    assign predict_taken   = pht[predict_index][1];
    assign predict_history = ghr;

    // Training interface index (combinational)
    logic [6:0] train_index;
    assign train_index = train_pc ^ train_history;

    // Sequential logic for GHR and PHT updates
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            for (int i = 0; i < 128; i++) begin
                pht[i] <= 2'b01; // Initialize to weakly not taken
            end
        end else begin
            // Update PHT on training request
            if (train_valid) begin
                if (train_taken) begin
                    if (pht[train_index] < 2'b11)
                        pht[train_index] <= pht[train_index] + 2'b01;
                end else begin
                    if (pht[train_index] > 2'b00)
                        pht[train_index] <= pht[train_index] - 2'b01;
                end
            end

            // Update GHR with training misprediction recovery taking precedence over prediction
            if (train_valid && train_mispredicted) begin
                ghr <= {train_history[5:0], train_taken};
            end else if (predict_valid) begin
                ghr <= {ghr[5:0], predict_taken};
            end
        end
    end

endmodule

